mapper.sql:
SELECT 'MANUAL_FEEDBACK' AS kind,feedback_id AS object_id,NULL AS version_id,revision,
  created_at AS occurred_at,CONCAT('MANUAL_FEEDBACK:',feedback_id,':-:',revision,':-') AS evidence_key
FROM review_feedback_revision WHERE owner_id=#{owner}

SELECT 'RECOLLECTION' AS kind,recollection_id AS object_id,id AS version_id,NULL AS revision,
  created_at AS occurred_at,CONCAT('RECOLLECTION:',recollection_id,':',id,':-:-') AS evidence_key
FROM review_recollection_version WHERE owner_id=#{owner}

SELECT 'REPLAY_JUDGMENT' AS kind,id AS object_id,NULL AS version_id,NULL AS revision,
  created_at AS occurred_at,CONCAT('REPLAY_JUDGMENT:',id,':-:-:-') AS evidence_key
FROM review_source_judgment WHERE owner_id=#{owner}

WHERE occurred_at >= #{start} AND occurred_at < #{end}

  AND (occurred_at < #{afterAt} OR (occurred_at=#{afterAt} AND evidence_key > #{afterKey}))

ORDER BY occurred_at DESC,evidence_key ASC LIMIT #{limit}

mapper.select:
SELECT id,owner_id,feedback_id,feedback_revision,revision,choice,created_at
FROM review_feedback_decision WHERE owner_id=#{owner} AND feedback_id=#{id} AND feedback_revision=#{revision}
ORDER BY revision DESC LIMIT 1

SELECT id,owner_id,baseline_session_id,baseline_question_id,baseline_answer_id,session_id,question_id,
  question_mode,created_at,baseline_kind,recollection_id,recollection_version_id,recollection_revision
FROM review_repractice WHERE owner_id=#{owner} AND id=#{id}

SELECT id FROM review_action_source WHERE owner_id=#{owner}
AND id > #{after}
ORDER BY id LIMIT #{limit}
